// Rewrites raw image hosts to the branded CloudFront CDN host.
//
// apiv2 returns media URLs pointing at the S3 bucket directly
// (tsgroup.s3.amazonaws.com / tsgrouptest.s3.amazonaws.com). An earlier
// CloudFront host (d2lpxiu1sq3srq.cloudfront.net) is also still scattered
// around the codebase. Both serve the same origin as cdn.travelshopbooking.com;
// consolidating on the branded host gives faster origin fetches + edge caching
// and one canonical host. This is a stop-gap done on the frontend; ideally the
// API would emit CDN URLs directly.
//
// NOTE: only the jpg conversions (tiny/thumb/high) and originals exist on S3 —
// the *_webp URLs apiv2 fabricates are 404. Next.js <Image> already re-encodes
// to webp on its own, so feed it the jpg source and let it handle the format.
const LEGACY_HOSTS = [
  "tsgroup.s3.amazonaws.com",
  "tsgrouptest.s3.amazonaws.com",
  "d2lpxiu1sq3srq.cloudfront.net",
];

const CDN_HOST = "cdn.travelshopbooking.com";

export default function cdnImage<T extends string | null | undefined>(
  url: T
): T {
  // Guard non-string callers too: API media fields are typed `string` but can
  // arrive as a truthy non-string (number/object), which would blow up on
  // `.replaceAll`. Return as-is rather than throw mid-render (caused tour-page
  // hydration failures — GlitchTip TSBNEXT-S / React #423/#425/#418).
  if (!url || typeof url !== "string") return url;
  let out = url as string;
  for (const host of LEGACY_HOSTS) {
    // split/join: replaceAll Safari <13.4 ve Chrome <85'te yok (TSBNEXT-S).
    out = out.split(host).join(CDN_HOST);
  }
  // Some source URLs arrive with a malformed single-slash protocol
  // ("https:/cdn..."); normalize it so the host swap stays a safe drop-in.
  out = out.split(`https:/${CDN_HOST}`).join(`https://${CDN_HOST}`);
  return out as T;
}
