import { apiClient } from "@/lib/apiClient";

// apiv3 B2C: POST /b2c/tours/{slug}/send-pdf → broşür e-postası. {success} döner.
// Uç misafire açıktır; login'liyken Bearer (`auth-token-v3`) gönderilir ki apiv3
// talebi kullanıcıya bağlasın (tour_broucher_requests.user_id). Token yoksa/geçersizse
// uç yine çalışır, talep anonim kaydedilir.
export default async function downloadRequest({
  data,
}: {
  data: { slug: string; first_name: string; email: string; token?: string };
}) {
  return apiClient(`/b2c/tours/${data.slug}/send-pdf`, {
    method: "POST",
    body: { first_name: data.first_name, email: data.email },
    ...(data.token ? { auth: "sanctum" as const, token: data.token } : {}),
  });
}
