import { hasCookie, getCookie } from "cookies-next";
import { apiClient } from "@/lib/apiClient";
import { getAttributionToken } from "@/lib/affiliateTracking";

// apiv3 B2C: POST /bookings/new-enquiry (tur "ask a question" → enquiry kaydı).
// Login'li kullanıcıda sanctum token gönderilir (contact_* sunucuda user'dan doldurulur);
// misafirde app-token. Her iki halde tarayıcı proxy'si X-App-Token ekler.
// 422 (validasyon / recaptcha) durumunda apiClient ApiError fırlatır (çağıran .catch ile yönetir).
export default async function sendMessage({ data }: { data: any }) {
  const token = hasCookie("auth-token-v3")
    ? (getCookie("auth-token-v3") as string)
    : undefined;

  // Enquiry sonradan booking'e dönüşebiliyor; atıf burada da taşınmazsa "önce soru sor,
  // sonra öde" akışında affiliate hak kaybeder.
  const attributionToken = getAttributionToken();

  return apiClient("/bookings/new-enquiry", {
    method: "POST",
    auth: token ? "sanctum" : "app-token",
    token,
    body: attributionToken ? { ...data, attribution_token: attributionToken } : data,
  });
}
